            // tens of GiB. Refuse a declaration past the in-memory ceiling
            // before anything is allocated.
            if content_len > MAX_DECODE_BYTES {
                return Err(CodecError::TooLong {
                    max: MAX_DECODE_BYTES,
                });
            }
            let mut dec = ruzstd::decoding::StreamingDecoder::new(payload)
                .map_err(|e| CodecError::Malformed(e.to_string()))?;
            let ceiling = usize::try_from(MAX_DECODE_BYTES).unwrap_or(usize::MAX);
            let mut out = Vec::with_capacity(ceiling.min(1 << 24));
            // Read one byte past the declared length to detect a longer stream.
            let limit = content_len
                .saturating_add(1)
                .min(MAX_DECODE_BYTES.saturating_add(1));
            (&mut dec)
                .take(limit)
                .read_to_end(&mut out)
                .map_err(|e| CodecError::Malformed(e.to_string()))?;
            out
